export type LiteSvmHandle = number;

export interface SerializableAccount {
  lamports: number;
  data: Uint8Array;
  owner: Uint8Array;
  executable: boolean;
  rent_epoch: number;
}

export interface OperationResult {
  error?: string | null;
}

export interface BytesResult {
  value?: Uint8Array;
  error?: string | null;
}

export interface AccountResult {
  value?: SerializableAccount | null;
  error?: string | null;
}

/** Inner instruction produced during transaction execution */
export interface InnerInstruction {
  /** Index of the instruction in the transaction */
  instruction_index: number;
  /** Program ID that executed this instruction */
  program_id: Uint8Array;
  /** Instruction data */
  data: Uint8Array;
  /** Account indices involved */
  accounts: number[];
}

/** Return data from a program invocation */
export interface TransactionReturnData {
  /** Program ID that returned the data */
  program_id: Uint8Array;
  /** The returned data bytes */
  data: Uint8Array;
}

/** Metadata for a successfully executed transaction */
export interface TransactionMetadata {
  /** Transaction signature (64 bytes) */
  signature: Uint8Array;
  /** Program logs emitted during execution */
  logs: string[];
  /** Inner instructions grouped by instruction index */
  inner_instructions: InnerInstruction[][];
  /** Total compute units consumed */
  compute_units_consumed: number;
  /** Return data from the transaction */
  return_data: TransactionReturnData;
  /** Transaction fee in lamports */
  fee: number;
}

/** Metadata for a failed transaction */
export interface FailedTransactionMetadata {
  /** The error that caused the transaction to fail */
  err: TransactionError;
  /** Metadata captured before failure */
  meta: TransactionMetadata;
}

/** Transaction error types */
export type TransactionError =
  | { InstructionError: [number, InstructionError] }
  | { DuplicateInstruction: number }
  | { InsufficientFundsForRent: { account_index: number } }
  | string;

/** Instruction error types */
export type InstructionError =
  | { Custom: number }
  | "GenericError"
  | "InvalidArgument"
  | "InvalidInstructionData"
  | "InvalidAccountData"
  | "AccountDataTooSmall"
  | "InsufficientFunds"
  | "IncorrectProgramId"
  | "MissingRequiredSignature"
  | "AccountAlreadyInitialized"
  | "UninitializedAccount"
  | "NotEnoughAccountKeys"
  | "AccountBorrowFailed"
  | "MaxSeedLengthExceeded"
  | "InvalidSeeds"
  | string;

/** Result envelope for successful transaction */
export interface TransactionResultOk {
  status: "ok";
  signature: string; // base58-encoded signature
  logs: string[];
  inner_instructions: InnerInstruction[][];
  compute_units_consumed: number;
  return_data: {
    program_id: number[];
    data: number[];
  };
  fee: number;
}

/** Result envelope for failed transaction */
export interface TransactionResultErr {
  status: "err";
  err: TransactionError;
  meta: {
    signature: string; // base58-encoded signature
    logs: string[];
    inner_instructions: InnerInstruction[][];
    compute_units_consumed: number;
    return_data: {
      program_id: number[];
      data: number[];
    };
    fee: number;
  };
}

/** Transaction result envelope - matches LiteSVM's TransactionResult */
export type TransactionResultEnvelope = TransactionResultOk | TransactionResultErr;

/** Simulation result with post-execution account states */
export interface SimulationResultOk {
  status: "ok";
  meta: {
    signature: string; // base58-encoded signature
    logs: string[];
    inner_instructions: InnerInstruction[][];
    compute_units_consumed: number;
    return_data: {
      program_id: number[];
      data: number[];
    };
    fee: number;
  };
  post_accounts: Array<{
    pubkey: number[];
    account: SerializableAccount;
  }>;
}

/** Simulation result for failed simulation */
export interface SimulationResultErr {
  status: "err";
  err: TransactionError;
  meta: {
    signature: string; // base58-encoded signature
    logs: string[];
    inner_instructions: InnerInstruction[][];
    compute_units_consumed: number;
    return_data: {
      program_id: number[];
      data: number[];
    };
    fee: number;
  };
}

/** Simulation result envelope */
export type SimulationResultEnvelope = SimulationResultOk | SimulationResultErr;

