export function get_account(handle: LiteSvmHandle, pubkey: Uint8Array): AccountResult {
  const pubkeyBuf = new Uint8Array(pubkey);
  return decodeResult(symbols.get_account(handle, pubkeyBuf, BigInt(pubkeyBuf.byteLength)));
}

export function set_account(
  handle: LiteSvmHandle,
  pubkey: Uint8Array,
  account: SerializableAccount,
): OperationResult {
  // Convert Uint8Array fields to regular arrays for proper JSON serialization
  const accountForJson = {
    lamports: account.lamports,
    data: Array.from(account.data),
    owner: Array.from(account.owner),
    executable: account.executable,
    rent_epoch: account.rent_epoch,
  };
  // Serialize account as length-prefixed JSON for FFI
  const jsonBytes = new TextEncoder().encode(JSON.stringify(accountForJson));
  // Create buffer with 4-byte length prefix + JSON data
  const encoded = new Uint8Array(4 + jsonBytes.length);
  const dataView = new DataView(encoded.buffer);
  dataView.setUint32(0, jsonBytes.length, true); // little-endian
  encoded.set(jsonBytes, 4);
  const ptr = Deno.UnsafePointer.of(encoded);
  if (!ptr) {
    throw new Error("Failed to create pointer for account data");
  }
  const pubkeyBuf = new Uint8Array(pubkey);
  return decodeResult(symbols.set_account(handle, pubkeyBuf, BigInt(pubkeyBuf.byteLength), ptr));
}

export function add_program(
  handle: LiteSvmHandle,
  programId: Uint8Array,
  programBytes: Uint8Array,
): OperationResult {
  const id = new Uint8Array(programId);
  const elf = new Uint8Array(programBytes);
  return decodeResult(
    symbols.add_program(
      handle,
      id,
      BigInt(id.byteLength),
      elf,
      BigInt(elf.byteLength),
    ),
  );
}

